/**
 * Unit tests for {@see OidcStepRouter}.
 */
#[AllowMockObjectsWithoutExpectations]
final class OidcStepRouterUnitTest extends TestCase
{
    private array $serverBackup = [];

    #[Override]
    protected function setUp(): void
    {
        $this->serverBackup = $_SERVER;
        $_SERVER['HTTPS'] = 'on';
        $_SERVER['HTTP_HOST'] = 'example.com';
        $_SERVER['SCRIPT_NAME'] = '/index.php';
    }

    #[Override]
    protected function tearDown(): void
    {
        $_SERVER = $this->serverBackup;
    }

    /**
     * Verifies explicit step mapping takes precedence.
     */
    public function testResolveUsesExplicitStep(): void
    {
        $login = $this->createMock(LoginForm::class);
        $consent = $this->createMock(TermsAndGdprConsentForm::class);

        $router = new OidcStepRouter(
            $consent,
            $this->createMock(ScopeConsentForm::class),
            $login,
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class),
            $this->createMock(WebAuthnLoginForm::class),
            $this->createMock(MagicLinkLoginForm::class),
            StepName::LOGIN->value
        );

        $result = $router->resolve(StepName::CONSENT->value, AuthenticationResult::consentRequired());

        $this->assertSame($consent, $result);
    }

    /**
     * Verifies error mapping is used when no step is provided.
     */
    public function testResolveUsesErrorMappingWhenNoStep(): void
    {
        $login = $this->createMock(LoginForm::class);
        $consent = $this->createMock(TermsAndGdprConsentForm::class);

        $router = new OidcStepRouter(
            $consent,
            $this->createMock(ScopeConsentForm::class),
            $login,
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class),
            $this->createMock(WebAuthnLoginForm::class),
            $this->createMock(MagicLinkLoginForm::class),
            StepName::LOGIN->value
        );

        $result = $router->resolve('', AuthenticationResult::consentRequired());

        $this->assertSame($consent, $result);
    }

    /**
     * Verifies fallback step is used when no mapping matches.
     */
    public function testResolveFallsBackWhenNoMatch(): void
    {
        $login = $this->createMock(LoginForm::class);
        $consent = $this->createMock(TermsAndGdprConsentForm::class);

        $router = new OidcStepRouter(
            $consent,
            $this->createMock(ScopeConsentForm::class),
            $login,
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class),
            $this->createMock(WebAuthnLoginForm::class),
            $this->createMock(MagicLinkLoginForm::class),
            StepName::LOGIN->value
        );

        $result = $router->resolve('', null);

        $this->assertSame($login, $result);
    }

    /**
     * Verifies run() proceeds when CSID is provided.
     */
    public function testRunProceedsWithCsid(): void
    {
        $authResponse = $this->createMock(PublicLoginAuthResponse::class);
        $form = $this->createMock(LoginForm::class);
        $form->expects($this->once())
            ->method('authenticate')
            ->willReturn(StepResult::proceed($authResponse, new ChallengesState(withMfa: false, session: false, username: 'user-1')));
        $router = new OidcStepRouter(
            $this->createMock(TermsAndGdprConsentForm::class),
            $this->createMock(ScopeConsentForm::class),
            $form,
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class),
            $this->createMock(WebAuthnLoginForm::class),
            $this->createMock(MagicLinkLoginForm::class),
            StepName::LOGIN->value
        );

        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);

        $authRequest = new AuthenticationRequest(
            client: new ClientData('client-123', ['code'], true),
            scope: 'openid',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );
        $input = new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: new ChallengesState(withMfa: false, session: false, username: 'user-1'),
            body: ['step' => StepName::LOGIN->value],
            request: $request
        );

        $response = new Response();
        $result = $router->run($input, $response, null, StepName::LOGIN->value, 'csid-123');

        $this->assertInstanceOf(StepResult::class, $result);
        $this->assertSame(StepResult::TYPE_PROCEED, $result?->type);
        $this->assertSame($authResponse, $result?->authResponse);
    }

    /**
     * Verifies run() renders when CSID is missing.
     */
    public function testRunRendersWithoutCsid(): void
    {
        $form = $this->createMock(LoginForm::class);
        $form->expects($this->once())
            ->method('render')
            ->willReturn(StepResult::render(new Response(), new ChallengesState()));
        $router = new OidcStepRouter(
            $this->createMock(TermsAndGdprConsentForm::class),
            $this->createMock(ScopeConsentForm::class),
            $form,
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class),
            $this->createMock(WebAuthnLoginForm::class),
            $this->createMock(MagicLinkLoginForm::class),
            StepName::LOGIN->value
        );

        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);

        $authRequest = new AuthenticationRequest(
            client: new ClientData('client-123', ['code'], true),
            scope: 'openid',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );
        $input = new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: new ChallengesState(withMfa: false, session: false, username: 'user-1'),
            body: ['step' => StepName::LOGIN->value],
            request: $request
        );

        $response = new Response();
        $result = $router->run($input, $response, null, StepName::LOGIN->value, null);

        $this->assertInstanceOf(StepResult::class, $result);
        $this->assertSame(StepResult::TYPE_RENDER, $result?->type);
        $this->assertSame(StepResult::TYPE_RENDER, $result?->type);
    }

    /**
     * Verifies run() returns null when the fallback step is not registered.
     */
    public function testRunReturnsNullWhenNoFormResolved(): void
    {
        $router = new OidcStepRouter(
            $this->createMock(TermsAndGdprConsentForm::class),
            $this->createMock(ScopeConsentForm::class),
            $this->createMock(LoginForm::class),
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class),
            $this->createMock(WebAuthnLoginForm::class),
            $this->createMock(MagicLinkLoginForm::class),
            'nonexistent_step'
        );

        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);
        $authRequest = new AuthenticationRequest(
            client: new ClientData('client-123', ['code'], true),
            scope: 'openid',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );
        $input = new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: new ChallengesState(),
            body: [],
            request: $request
        );

        $result = $router->run($input, new Response(), null, null, null);

        $this->assertNull($result);
    }
}
